contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function test(address _owner, address _recipient) public {
        // caller of c.withdrawAll must be owner; fund caller via constructor parameter assumption
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        require(ownerBefore == _owner);
        c.withdrawAll(_recipient); if (__ESBMC_reverted()) return;
        assert(c.owner() == ownerBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

