pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _test(address _owner, address _recipient) internal {
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        _owner = ownerBefore;
        try c.withdrawAll(_recipient) {} catch { return; }
        assertTrue(c.owner() == ownerBefore);
    }

    function testFuzz_test(address _owner, address _recipient) public {
        vm.assume(_recipient.code.length == 0 && uint160(_recipient) > 0xffff && _recipient != address(this) && _recipient != address(c) && _recipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _recipient != 0x000000000000000000636F6e736F6c652e6c6f67 && _recipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _recipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(_owner, _recipient);
    }

    receive() external payable {}

    fallback() external payable {}
}
